// Smart Numbered Pagination with Dots
document.addEventListener('DOMContentLoaded', function () {
    var container = document.getElementById('page-numbers-container');
    if (!container) return;

    var url = window.location.href;
    var currentPage = 1;

    // Determine current page based on URL
    if (url === window.location.origin + '/' || url.indexOf('updated-max=') === -1) {
        currentPage = 1;
        localStorage.setItem('blogCurrentPage', '1');
    } else {
        var storedPage = localStorage.getItem('blogCurrentPage');
        if (storedPage) {
            currentPage = parseInt(storedPage, 10);
        } else {
            currentPage = 2;
        }
    }

    // Calculate total pages
    var totalPosts = 16; // Update this when you add/remove posts
    var postsPerPage = 4;
    var totalPages = Math.ceil(totalPosts / postsPerPage);

    // Generate smart pagination with dots
    function generatePagination(current, total) {
        var pages = [];
        var delta = 1; // Number of pages to show on each side of current page

        // Always show first page
        pages.push(1);

        // Calculate range around current page
        for (var i = current - delta; i <= current + delta; i++) {
            if (i > 1 && i < total) {
                pages.push(i);
            }
        }

        // Always show last page
        if (total > 1) {
            pages.push(total);
        }

        // Remove duplicates and sort
        pages = pages.filter(function (value, index, self) {
            return self.indexOf(value) === index;
        }).sort(function (a, b) { return a - b; });

        // Build HTML with dots
        var html = '';
        var prev = 0;

        pages.forEach(function (page) {
            // Add dots if there's a gap
            if (page - prev > 1) {
                html += '<span class="pagination-dots">...</span>';
            }

            // Add page number
            if (page === current) {
                html += '<span class="pagination-btn active">' + page + '</span>';
            } else {
                html += '<a href="#" class="pagination-btn page-num-btn" data-page="' + page + '">' + page + '</a>';
            }

            prev = page;
        });

        return html;
    }

    container.innerHTML = generatePagination(currentPage, totalPages);

    // Handle page number clicks
    var pageNumBtns = document.querySelectorAll('.page-num-btn');
    pageNumBtns.forEach(function (btn) {
        btn.addEventListener('click', function (e) {
            e.preventDefault();
            var targetPage = parseInt(this.getAttribute('data-page'), 10);
            localStorage.setItem('blogCurrentPage', targetPage.toString());

            // Navigate based on page number
            if (targetPage === 1) {
                window.location.href = '/';
            } else if (targetPage > currentPage) {
                // Going forward - use Next button
                var nextBtn = document.getElementById('next-btn');
                if (nextBtn) {
                    window.location.href = nextBtn.href;
                }
            } else {
                // Going backward - use Previous button
                var prevBtn = document.getElementById('prev-btn');
                if (prevBtn) {
                    window.location.href = prevBtn.href;
                }
            }
        });
    });

    // Update localStorage on Previous/Next clicks
    var prevBtn = document.getElementById('prev-btn');
    var nextBtn = document.getElementById('next-btn');

    if (prevBtn) {
        prevBtn.addEventListener('click', function () {
            var prevPage = Math.max(1, currentPage - 1);
            localStorage.setItem('blogCurrentPage', prevPage.toString());
        });
    }

    if (nextBtn) {
        nextBtn.addEventListener('click', function () {
            var nextPage = Math.min(totalPages, currentPage + 1);
            localStorage.setItem('blogCurrentPage', nextPage.toString());
        });
    }
});
