// Mobile Submenu Toggle
document.addEventListener('DOMContentLoaded', function () {
    // Only run on mobile
    if (window.innerWidth <= 900) {
        // Handle nested submenus (Categories -> Software Engineering, etc.)
        var submenuItems = document.querySelectorAll('.has-submenu > .dropdown-link');

        submenuItems.forEach(function (item) {
            item.addEventListener('click', function (e) {
                e.preventDefault();

                var parent = this.parentElement;
                var isActive = parent.classList.contains('active');

                // Close all other submenus
                document.querySelectorAll('.has-submenu.active').forEach(function (el) {
                    if (el !== parent) {
                        el.classList.remove('active');
                    }
                });

                // Toggle current submenu
                if (isActive) {
                    parent.classList.remove('active');
                } else {
                    parent.classList.add('active');
                }
            });
        });

        // Handle regular dropdowns (Companies, Job Type, Location)
        var navItems = document.querySelectorAll('.nav-item:not(.categories-dropdown) > .nav-link');

        console.log('Found ' + navItems.length + ' mobile dropdown headers');

        navItems.forEach(function (link) {
            link.addEventListener('click', function (e) {
                e.preventDefault();
                e.stopPropagation();

                var parent = this.parentElement;
                var dropdown = parent.querySelector('.dropdown-menu');

                // Use data attribute for more reliable state tracking
                var wasOpen = parent.getAttribute('data-dropdown-open') === 'true';

                console.log('Clicked:', this.textContent.trim(), 'Was open:', wasOpen, 'Has active class:', parent.classList.contains('active'));

                // Close all other nav-item dropdowns first
                document.querySelectorAll('.nav-item:not(.categories-dropdown)').forEach(function (el) {
                    if (el !== parent) {
                        el.classList.remove('active');
                        el.setAttribute('data-dropdown-open', 'false');
                        var otherDropdown = el.querySelector('.dropdown-menu');
                        if (otherDropdown) {
                            otherDropdown.style.maxHeight = '0';
                            otherDropdown.style.opacity = '0';
                            otherDropdown.style.visibility = 'hidden';
                            otherDropdown.style.padding = '0';
                            otherDropdown.style.overflowY = 'hidden';
                        }
                    }
                });

                // Toggle current dropdown based on previous state
                if (wasOpen) {
                    // It was open, so close it
                    parent.classList.remove('active');
                    parent.setAttribute('data-dropdown-open', 'false');
                    if (dropdown) {
                        dropdown.style.cssText = 'max-height: 0 !important; opacity: 0 !important; visibility: hidden !important; padding: 0 !important; overflow-y: hidden !important;';
                    }
                    console.log('✓ Closed dropdown');
                } else {
                    // It was closed, so open it
                    parent.classList.add('active');
                    parent.setAttribute('data-dropdown-open', 'true');
                    if (dropdown) {
                        dropdown.style.cssText = 'max-height: 400px !important; opacity: 1 !important; visibility: visible !important; padding: 10px 0 !important; overflow-y: auto !important;';
                    }
                    console.log('✓ Opened dropdown');
                }
            });
        });
    }
});
