document.addEventListener("DOMContentLoaded", function () {
    // Select all apply buttons, wait messages, and timers by class
    const applyBtns = document.querySelectorAll('.dynamic-apply-btn');
    const waitMsgs = document.querySelectorAll('.wait-msg'); 
    const timers = document.querySelectorAll('.timer');

    if (applyBtns.length > 0 && waitMsgs.length > 0) {
        const postBody = document.querySelector('.post-body');
        if (postBody) {
            // Logic to find the application link inside the post
            let targetLink = postBody.querySelector('a[href*="linkedin.com"], a[href*="forms.gle"], a[href^="mailto:"]');

            // If no specific link found, look for any link with "apply" in text or any http/https link
            if (!targetLink) {
                const allLinks = postBody.querySelectorAll('a');

                for (let link of allLinks) {
                    // Skip if link contains an image (Blogger wraps images in <a> tags)
                    if (link.querySelector('img')) {
                        continue;
                    }

                    // Skip Blogger CDN URLs
                    if (link.href.includes('blogger.googleusercontent.com') ||
                        link.href.includes('blogspot.com')) {
                        continue;
                    }

                    const linkText = link.textContent.toLowerCase().trim();
                    const linkHref = link.href.toLowerCase();

                    // Check if link text contains "apply", "website", "career" or if it's an external http/https link
                    if (linkText.includes('apply') ||
                        linkText.includes('website') ||
                        linkText.includes('career') ||
                        (link.href.startsWith('http') && !link.href.includes(window.location.hostname))) {
                        targetLink = link;
                        break;
                    }
                }
            }

            if (targetLink) {
                let finalHref = '';
                let targetAttr = '';

                if (targetLink.href.startsWith('mailto:')) {
                    const emailAddress = targetLink.href.replace('mailto:', '');
                    const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
                    finalHref = isMobile ? 'mailto:' + emailAddress : 'https://mail.google.com/mail/?view=cm&fs=1&to=' + emailAddress;
                } else {
                    finalHref = targetLink.href;
                    targetAttr = '_blank';
                }

                // Update ALL apply buttons
                applyBtns.forEach(btn => {
                    btn.href = finalHref;
                    if (targetAttr) btn.setAttribute('target', targetAttr);
                });

                // Only hide the link if it doesn't contain an image
                if (!targetLink.querySelector('img')) {
                    targetLink.style.display = 'none';
                }
            }
        }

        // 15 Second Countdown
        let count = 15;
        const interval = setInterval(() => {
            count--;
            timers.forEach(t => { if (t) t.textContent = count; });

            if (count <= 0) {
                clearInterval(interval);

                // Hide ALL wait messages
                waitMsgs.forEach(msg => {
                    msg.style.display = 'none';
                });

                // Show ALL apply buttons
                applyBtns.forEach(btn => {
                    btn.style.display = 'inline-block';
                });
            }
        }, 1000);
    }

    // Mobile Dropdown Toggles
    const mobileNavItems = document.querySelectorAll('.nav-item');
    mobileNavItems.forEach(item => {
        const link = item.querySelector('.nav-link');
        link.addEventListener('click', function (e) {
            if (window.innerWidth <= 900) {
                e.preventDefault();
                item.classList.toggle('active');
            }
        });
    });
});
