// Mobile Menu Toggle & Job Categories Collapse
document.addEventListener('DOMContentLoaded', function () {
    var mobileMenuBtn = document.getElementById('mobile-menu-btn');
    var mobileCloseBtn = document.getElementById('mobile-close-btn');
    var mobileOverlay = document.getElementById('mobile-overlay');
    var navMenu = document.querySelector('.nav-menu');
    var jobCategoriesToggle = document.getElementById('job-categories-toggle');
    var jobCategoriesList = document.getElementById('job-categories-list');
    var jobCategoriesMobile = document.querySelector('.job-categories-mobile');

    // Open mobile menu
    if (mobileMenuBtn) {
        mobileMenuBtn.addEventListener('click', function () {
            navMenu.classList.add('active');
            mobileOverlay.classList.add('active');
            document.body.style.overflow = 'hidden';
        });
    }

    // Close mobile menu
    function closeMobileMenu() {
        navMenu.classList.remove('active');
        mobileOverlay.classList.remove('active');
        document.body.style.overflow = '';
    }

    if (mobileCloseBtn) {
        mobileCloseBtn.addEventListener('click', closeMobileMenu);
    }

    if (mobileOverlay) {
        mobileOverlay.addEventListener('click', closeMobileMenu);
    }

    // Toggle Job Categories
    if (jobCategoriesToggle) {
        jobCategoriesToggle.addEventListener('click', function (e) {
            e.preventDefault();
            jobCategoriesMobile.classList.toggle('active');
            jobCategoriesList.classList.toggle('active');
        });
    }

    // Handle nested subcategories in job categories
    var nestedItems = document.querySelectorAll('.has-submenu-mobile > .dropdown-link');
    nestedItems.forEach(function (link) {
        link.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();

            var parent = this.parentElement;
            var submenu = parent.querySelector('.submenu-mobile');
            var isActive = parent.classList.contains('active');

            // Close all other nested submenus
            document.querySelectorAll('.has-submenu-mobile.active').forEach(function (el) {
                if (el !== parent) {
                    el.classList.remove('active');
                    var otherSubmenu = el.querySelector('.submenu-mobile');
                    if (otherSubmenu) {
                        otherSubmenu.classList.remove('active');
                    }
                }
            });

            // Toggle current submenu
            if (isActive) {
                parent.classList.remove('active');
                submenu.classList.remove('active');
            } else {
                parent.classList.add('active');
                submenu.classList.add('active');
            }
        });
    });
});
