// Search Functionality
document.addEventListener('DOMContentLoaded', function() {
    const searchBtn = document.querySelector('.search-btn');
    const searchOverlay = document.getElementById('searchOverlay');
    const searchInput = document.getElementById('searchInput');
    const searchClose = document.getElementById('searchClose');
    const searchSuggestions = document.getElementById('searchSuggestions');

    // Popular search terms and categories
    const searchData = [
        { text: 'Software Engineering Jobs', icon: 'fa-code', url: '/search/label/Software-Engineering' },
        { text: 'Internship Opportunities', icon: 'fa-graduation-cap', url: '/search/label/Internship' },
        { text: 'Full Stack Developer', icon: 'fa-laptop-code', url: '/search/label/Full-Stack' },
        { text: 'UI/UX Design', icon: 'fa-palette', url: '/search/label/UI-UX' },
        { text: 'Backend Development', icon: 'fa-server', url: '/search/label/Backend' },
        { text: 'Frontend Development', icon: 'fa-window-maximize', url: '/search/label/Frontend' },
        { text: 'Mobile App Development', icon: 'fa-mobile-screen', url: '/search/label/Mobile-Development' },
        { text: 'DevOps & Cloud', icon: 'fa-cloud', url: '/search/label/DevOps' },
        { text: 'AI & Data Science', icon: 'fa-brain', url: '/search/label/AI-Data-Science' },
        { text: 'Machine Learning', icon: 'fa-robot', url: '/search/label/Machine-Learning' },
        { text: 'Digital Marketing', icon: 'fa-bullhorn', url: '/search/label/Digital-Marketing' },
        { text: 'IFS R&D', icon: 'fa-building', url: '/search/label/IFS' },
        { text: 'Virtusa', icon: 'fa-building', url: '/search/label/Virtusa' },
        { text: 'WSO2', icon: 'fa-building', url: '/search/label/WSO2' },
        { text: 'Remote Jobs', icon: 'fa-house-laptop', url: '/search/label/Remote' },
        { text: 'Full Time Jobs', icon: 'fa-briefcase', url: '/search/label/Full%20Time' }
    ];

    // Open search overlay
    if (searchBtn) {
        searchBtn.addEventListener('click', function() {
            searchOverlay.classList.add('active');
            searchInput.focus();
            showDefaultSuggestions();
        });
    }

    // Close search overlay
    function closeSearch() {
        searchOverlay.classList.remove('active');
        searchInput.value = '';
        searchSuggestions.innerHTML = '';
        searchSuggestions.classList.remove('active');
    }

    if (searchClose) {
        searchClose.addEventListener('click', closeSearch);
    }

    // Close on overlay click
    searchOverlay.addEventListener('click', function(e) {
        if (e.target === searchOverlay) {
            closeSearch();
        }
    });

    // Close on Escape key
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && searchOverlay.classList.contains('active')) {
            closeSearch();
        }
    });

    // Show default suggestions
    function showDefaultSuggestions() {
        const html = searchData.slice(0, 8).map(item => `
            <div class="suggestion-item" data-url="${item.url}">
                <i class="fa-solid ${item.icon} suggestion-icon"></i>
                <span class="suggestion-text">${item.text}</span>
            </div>
        `).join('');

        searchSuggestions.innerHTML = html;
        searchSuggestions.classList.add('active');
        addSuggestionClickListeners();
    }

    // Search input handler
    searchInput.addEventListener('input', function() {
        const query = this.value.trim().toLowerCase();

        if (query.length === 0) {
            showDefaultSuggestions();
            return;
        }

        // Filter suggestions based on query
        const filtered = searchData.filter(item => 
            item.text.toLowerCase().includes(query)
        );

        if (filtered.length > 0) {
            const html = filtered.map(item => {
                const highlightedText = item.text.replace(
                    new RegExp(query, 'gi'),
                    match => `<strong>${match}</strong>`
                );
                return `
                    <div class="suggestion-item" data-url="${item.url}">
                        <i class="fa-solid ${item.icon} suggestion-icon"></i>
                        <span class="suggestion-text">${highlightedText}</span>
                    </div>
                `;
            }).join('');

            searchSuggestions.innerHTML = html;
            searchSuggestions.classList.add('active');
        } else {
            searchSuggestions.innerHTML = `
                <div class="no-results">
                    <i class="fa-solid fa-search" style="font-size: 40px; color: #ddd; margin-bottom: 15px;"></i>
                    <p>No results found for "<strong>${query}</strong>"</p>
                    <p style="font-size: 13px; margin-top: 10px;">Try searching for jobs, companies, or categories</p>
                </div>
            `;
            searchSuggestions.classList.add('active');
        }

        addSuggestionClickListeners();
    });

    // Handle Enter key for search
    searchInput.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') {
            const query = this.value.trim();
            if (query) {
                window.location.href = '/search?q=' + encodeURIComponent(query);
            }
        }
    });

    // Add click listeners to suggestions
    function addSuggestionClickListeners() {
        document.querySelectorAll('.suggestion-item').forEach(item => {
            item.addEventListener('click', function() {
                const url = this.getAttribute('data-url');
                if (url) {
                    window.location.href = url;
                }
            });
        });
    }
});
